from pathlib import Path
import os,subprocess
project=Path('/opt/telegram-robot-leads')
source=Path('/opt/telegram-leads-optin')
target=project/'optin'
files=[project/'scripts/growth_radar.py',project/'scripts/telegram-robot-leads-status.sh',project/'docs/OPT_IN_GROWTH.md']
before=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=14)
if before.returncode:raise RuntimeError('PM2 status unavailable')
import json
apps={a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(before.stdout)}
if apps.get('telegram-robot-leads')!='online' or apps.get('iptvpn_bot')!='online':
 raise RuntimeError('Telegram bots not online; refusing relocation')
if not source.is_dir() or source.is_symlink() or target.exists() or target.is_symlink():
 raise RuntimeError('Source or destination not in the expected state')
if not all(f.is_file() and not f.is_symlink() for f in files):
 raise RuntimeError('Expected project-owned text files absent')
old='/opt/telegram-leads-optin'
new='/opt/telegram-robot-leads/optin'
original={f:f.read_bytes() for f in files}
if sum(blob.count(old.encode()) for blob in original.values())<4:
 raise RuntimeError('Expected project references not verified')
if not (source/'PROVENANCE.txt').is_file() or not (source/'scripts').is_dir():
 raise RuntimeError('Opt-in project provenance not verified')
if any(f.is_symlink() for f in source.rglob('*')):
 raise RuntimeError('Unverified links in opt-in staging')
changed=[]
try:
 source.rename(target)
 for f,blob in original.items():
  f.write_bytes(blob.replace(old.encode(),new.encode()))
  changed.append(f)
 rc=subprocess.run(['bash','-n',str(project/'scripts/telegram-robot-leads-status.sh')],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=7).returncode
 if rc:raise RuntimeError('Status shell syntax check failed')
 rc=subprocess.run([str(project/'.venv/bin/python'),'-m','py_compile',str(project/'scripts/growth_radar.py')],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=9).returncode
 if rc:raise RuntimeError('Python syntax check failed')
 rc=subprocess.run([str(project/'.venv/bin/python'),str(project/'scripts/growth_radar.py'),'--help'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=9).returncode
 if rc:raise RuntimeError('Growth radar help failed')
 if not (target/'PROVENANCE.txt').is_file() or not (target/'scripts/growth_tracker.py').is_file():
  raise RuntimeError('Opt-in files missing after relocation')
 if source.exists():raise RuntimeError('Old opt-in directory still present')
 after=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=14)
 if after.returncode:raise RuntimeError('PM2 status verification unavailable')
 again={a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(after.stdout)}
 if any(again.get(name)!='online' for name in ('iptvpn_bot','telegram-robot-leads')):
  raise RuntimeError('A Telegram bot changed online state')
except Exception as e:
 for f,blob in original.items():f.write_bytes(blob)
 if target.exists() and not source.exists():target.rename(source)
 print('ROLLBACK_APPLIED=yes')
 raise
print('OPTIN_OLD_PATH_REMOVED=yes')
print('OPTIN_NEW_PATH='+str(target))
print('OPTIN_UPDATED_FILES='+','.join(str(x.relative_to(project)) for x in changed))
print('IPTVPN_BOT=online')
print('TELEGRAM_ROBOT_LEADS=online')
print('OPTIN_CONSOLIDATION=PASS')
PY
